static void memory_capture(m4_runtime::Runtime&r,Record&rec,bool before){auto&v=before?rec.memory_before:rec.memory_after;for(unsigned i=0;i<5;++i)r.memory().read({observed_pages[i]},std::as_writable_bytes(std::span{v.data()+4096*i,4096}));}
int main(){try{
 SetErrorMode(SEM_FAILCRITICALERRORS|SEM_NOGPFAULTERRORBOX);
 auto game=readfile(environment("MW34_CMN_GAME"),2384384),provider=readfile(environment("MW34_CMN_PROVIDER"),266293),pack=readfile(environment("MW34_CMN_PACK"),12324);auto supplied=environment("MW34_CMN_SUPPLIED");Output output(environment("MW34_CMN_OUTPUT"));
 std::vector<std::byte>observed;unsigned id{};
 for(unsigned repeat=0;repeat<2;++repeat)for(auto cw:m4_crt_probe::controls)for(unsigned top:{0U,7U}){
  auto runtime=m4_runtime::Runtime::from_admitted_image(game);Registry registry(runtime);require(registry.admit(provider,pack),"Actual native provider source admission failed");
  std::array<std::uint8_t,4096>stack;stack.fill(0xa5);runtime.memory().write({0x20001000},std::as_bytes(std::span{stack}));runtime.memory().store<unsigned>({0x20001800},capture_gate.value);
  Record r{};r.id=id++;r.repeat=repeat;r.cw=cw;r.top=top;r.native=1;State state;seed(state,cw,top,0,repeat);r.before=cpu(state);std::memcpy(r.state_before.data(),&state,3504);project(state,r.fx_before,r.env_before);memory_capture(runtime,r,true);
  {Isolation isolate;require(registry.initialize(state),registry.first_fault()?registry.first_fault()->detail:"Compiled actual writer failed");isolate.finish(r);}require(r.host_restored,"Full native host restoration failed");
  auto global=registry.resolve_data(game_iat);require(global&&*global==provider_global,"Native resulting global/data import route failed");r.data_address=global->value;r.data_value=runtime.memory().load<unsigned>(*global);require(r.data_value==buffer_start.value,"Typed native buffer domain failed");
  const auto&host=registry.host_snapshot();r.input_bytes=static_cast<unsigned>(host.bytes.size());r.input_regions=static_cast<unsigned>(host.regions.size());r.host_pointer=host.borrowed_pointer;r.api_before=api_record(host.before);r.api_after=api_record(host.after);if(observed.empty()){observed=host.bytes;prefix(output,true,supplied,observed);}require(observed==host.bytes,"Actual per-process commandline changed");
  r.after=cpu(state);std::memcpy(r.state_after.data(),&state,3504);project(state,r.fx_after,r.env_after);memory_capture(runtime,r,false);r.service_before=cpu(registry.service_state_before());r.service_after=cpu(registry.service_state_after());
  std::memcpy(r.service_fx_before.data(),registry.service_fx_before().data(),512);std::memcpy(r.service_fx_after.data(),registry.service_fx_after().data(),512);std::memcpy(r.service_env_before.data(),registry.service_env_before().data(),28);std::memcpy(r.service_env_after.data(),registry.service_env_after().data(),28);
  auto route=registry.route();r.route={route.target,route.return_pc,route.entry_esp,route.exit_esp,route.completed};r.events=static_cast<unsigned>(registry.events().size());for(unsigned j=0;j<r.events;++j){auto e=registry.events()[j];std::array<unsigned,5>a{e.pc,e.address,e.value,e.width,e.operation};std::copy(a.begin(),a.end(),r.event_data.begin()+j*5);}r.capture=registry.compiled_capture_complete();
  std::vector<std::byte>owned(observed.size());runtime.memory().read(buffer_start,owned);require(owned==observed,"Actual checked guest owning snapshot differs");output.write(&r,sizeof(r));output.write(host.regions.data(),static_cast<unsigned>(host.regions.size()*sizeof(HostRegion)));output.write(owned.data(),static_cast<unsigned>(owned.size()));
 }
 require(id==cases,"Native command-line corpus extent failed");output.commit();std::cout<<"48 actual native writer/data-route cases captured\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
